source_metadata.sparql_query:
SELECT ?edition ?editionLabel ?series ?seriesLabel ?winner ?winnerLabel ?date ?ordinal WHERE {
  {
    SELECT ?edition ?series ?winner ?date (COUNT(DISTINCT ?earlierEdition) + 1 AS ?ordinal) WHERE {
      ?edition wdt:P179 ?series;
               wdt:P585 ?date;
               wdt:P1346 ?winner.
      FILTER(?date >= "2026-01-01T00:00:00Z"^^xsd:dateTime)
      FILTER(?date <= "2026-05-06T23:59:59Z"^^xsd:dateTime)
      FILTER NOT EXISTS {
        ?edition wdt:P1346 ?otherWinner.
        FILTER(?otherWinner != ?winner)
      }
      OPTIONAL {
        ?earlierEdition wdt:P179 ?series;
                      wdt:P585 ?earlierDate.
        FILTER(?earlierDate < ?date)
      }
    }
    GROUP BY ?edition ?series ?winner ?date
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 5
